// .vscode/mcp.json — editor format, as in the SQL MCP Server quickstart
{
  "servers": {
    "sql-mcp-server": {
      "type": "stdio",
      "command": "dab",
      "args": ["start", "--mcp-stdio", "role:reader",
               "--config", "${workspaceFolder}/dab-config.json"]
    }
  }
}
// Copilot harness: put the same server in .mcp.json at the workspace root,
// under "mcpServers" instead of "servers".
// dab-config.json grants the "reader" role only the read action.
